steps.sql:
SELECT COUNT(DISTINCT source_file) AS files
FROM staging_raw_sellout
WHERE source_file LIKE 'export_2025%';

queries.sql:
SELECT COUNT(DISTINCT source_file) AS files,
       COUNT(*) AS raw_rows
FROM staging_raw_sellout;

SELECT COUNT(*) AS after_dedup
FROM (SELECT DISTINCT sale_date, customer_name, sku_code, units, revenue, source_file
      FROM staging_raw_sellout) t;
